from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingStorage,
)
from rasa.core.config.available_endpoints import RecordingConfig

_SUPPORTED_RECORDING_PROVIDERS = ("s3", "gcs", "azure", "local")

__all__ = ["create_recording_storage"]


def create_recording_storage(config: RecordingConfig) -> RecordingStorage:
    """Build the storage backend for the configured recordings provider.

    Args:
        config: Call recording configuration selecting a storage provider.

    Returns:
        Storage backend for the configured provider.

    Raises:
        ValueError: ``provider`` was omitted or is not supported.
    """
    provider = config.require_provider()
    if provider == "s3":
        from rasa.core.channels.voice_stream.call_recording.storages.s3 import (
            S3RecordingStorage,
        )

        return S3RecordingStorage(config)
    if provider == "gcs":
        from rasa.core.channels.voice_stream.call_recording.storages.gcs import (
            GCSRecordingStorage,
        )

        return GCSRecordingStorage(config)
    if provider == "azure":
        from rasa.core.channels.voice_stream.call_recording.storages.azure import (
            AzureRecordingStorage,
        )

        return AzureRecordingStorage(config)
    if provider == "local":
        from rasa.core.channels.voice_stream.call_recording.storages.local import (
            LocalRecordingStorage,
        )

        return LocalRecordingStorage(config)
    supported = ", ".join(
        f"'{provider}'" for provider in _SUPPORTED_RECORDING_PROVIDERS
    )
    raise ValueError(
        "Unsupported recordings provider "
        f"'{provider}'. Supported providers: {supported}."
    )
